    [Theory]
    [MemberData(nameof(Mistakes))]
    public void NoEmptyChoiceAtTheBottomIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The choosings giving back the empty choice; ways of stepping to a target, the target found a choice of its own and
    /// running out of steps first none; how many choices there are, counted and not listed; the even numbers of a list; and
    /// every prefix of a list, the empty prefix given at the bottom.
    /// </summary>
    [Theory]
    [InlineData("choices.cpp", "#include <iostream>\n#include <vector>\n\nstd::vector<std::vector<int>> choices(int from, int to, int count) {\n    if (count == 0) {\n        return {{}};\n    }\n    std::vector<std::vector<int>> found;\n    for (int first = from; first <= to - count; first++) {\n        for (std::vector<int> rest : choices(first + 1, to, count - 1)) {\n            rest.insert(rest.begin(), first);\n            found.push_back(rest);\n        }\n    }\n    return found;\n}\n\nint main() {\n    std::vector<std::vector<int>> found = choices(1, 6, 3);\n    for (std::size_t c = 0; c < found.size(); c++) {\n        if (c > 0) std::cout << \"|\";\n        for (std::size_t n = 0; n < found[c].size(); n++) std::cout << (n > 0 ? \" \" : \"\") << found[c][n];\n    }\n    std::cout << std::endl;\n    return 0;\n}\n")]
    [InlineData("choices.dart", "List<List<int>> choices(int from, int to, int count) {\n  if (count == 0) {\n    return [[]];\n  }\n  final found = <List<int>>[];\n  for (var first = from; first <= to - count; first++) {\n    for (final rest in choices(first + 1, to, count - 1)) {\n      found.add([first, ...rest]);\n    }\n  }\n  return found;\n}\n\nvoid main() {\n  print(choices(1, 6, 3).map((choice) => choice.join(' ')).join('|'));\n}\n")]
