    [InlineData("count_choices.js", "// How many choices there are, counted and not listed: with nothing left to choose there is one way - prints 10.\nfunction countChoices(from, to, count) {\n  if (count === 0) return 1;\n  let total = 0;\n  for (let first = from; first <= to - count; first++) {\n    total += countChoices(first + 1, to, count - 1);\n  }\n  return total;\n}\n\nconsole.log(countChoices(1, 6, 3));\n")]
    [InlineData("evens.py", "# The even numbers of a list, called on the rest of it, giving nothing for an empty list - which is right: prints 2 4.\ndef evens(numbers):\n    if len(numbers) == 0:\n        return []\n    first, rest = numbers[0], numbers[1:]\n    return ([first] if first % 2 == 0 else []) + evens(rest)\n\n\nprint(*evens([1, 2, 3, 4, 5]))\n")]
    [InlineData("paths.py", "# Every way of stepping 1 or 2 from a number to a target within some steps: the target found is a choice of its own, and\n# running out of steps first gives none, as meant - prints 1 2 3|1 3.\ndef ways(position, target, steps):\n    if position == target:\n        return [[position]]\n    if steps == 0 or position > target:\n        return []\n    return [[position] + rest for step in (1, 2) for rest in ways(position + step, target, steps - 1)]\n\n\nprint(\"|\".join(\" \".join(str(number) for number in way) for way in ways(1, 3, 2)))\n")]
    [InlineData("Prefixes.java", "import java.util.ArrayList;\nimport java.util.List;\n\n// Every prefix of a list, built from the prefixes of the shorter one - the empty prefix given at the bottom: prints [] [1] [1, 2].\npublic class Prefixes {\n    static List<List<Integer>> prefixes(List<Integer> items) {\n        List<List<Integer>> found = new ArrayList<>();\n        if (items.size() == 0) {\n            found.add(new ArrayList<>());\n            return found;\n        }\n        found.addAll(prefixes(items.subList(0, items.size() - 1)));\n        found.add(new ArrayList<>(items));\n        return found;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(String.join(\" \", prefixes(List.of(1, 2)).stream().map(Object::toString).toList()));\n    }\n}\n")]
    public void TheEmptyChoiceGivenIsLeftAlone(string fileName, string code)
    {
        // Each check of the file's own language, as FixFinder runs them.
        var file = Program(fileName, code);
        var extension = Path.GetExtension(fileName).ToLowerInvariant();
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("empty-choice-missing", StringComparison.Ordinal) && pattern.Extensions.Contains(extension))
            .SelectMany(pattern => pattern.Find(file)));
    }
}
